      sourceToAnalysis: { scaleX, scaleY, offsetX: 0, offsetY: 0 },
      analysisToSource: { scaleX: 1 / scaleX, scaleY: 1 / scaleY, offsetX: 0, offsetY: 0 },
      roundTripMaxErrorPx: 0,
